"""Bidirectional mapping between PydanticAI types and the gigachat SDK models.

**Outgoing direction (pydantic_ai → GigaChat)**: we build plain ``dict`` payloads
and pass them straight to ``GigaChat.achat()`` / ``astream()`` (the SDK accepts
``Union[Chat, Dict[str, Any], str]``). Going through dicts lets us forward the
caller's JSON Schema for tool parameters verbatim — the SDK's typed
``FunctionParameters`` model would lossily coerce nested schema features like
``enum``, ``items``, or arbitrary ``additionalProperties``.

**Incoming direction (GigaChat → pydantic_ai)**: we consume the SDK's typed
Pydantic models (``ChatCompletion``, ``ChatCompletionChunk``, ``Messages``,
``Usage``) so all fields are validated and statically typed.

Limitations carried over from the previous httpx implementation:

- ``UserPromptPart`` multimodal content is flattened to text.
- ``RetryPromptPart`` is rendered back to the model as a ``user`` turn so the
  model can correct itself.
- We deliberately omit ``return_parameters`` from the outgoing function schema
  — see :func:`tools_to_gigachat`.
"""

from __future__ import annotations

import json
from collections.abc import Iterable, Sequence
from typing import Any, cast

from gigachat.models import ChatCompletionChunk, Messages, Usage
from pydantic_ai.messages import (
    FinishReason,
    ModelMessage,
    ModelRequest,
    ModelResponse,
    ModelResponsePart,
    RetryPromptPart,
    SystemPromptPart,
    TextPart,
    ToolCallPart,
    ToolReturnPart,
    UserPromptPart,
)
from pydantic_ai.tools import ToolDefinition

# ---------------------------------------------------------------------------
# pydantic_ai -> GigaChat (outgoing dicts)
# ---------------------------------------------------------------------------


def messages_to_gigachat(messages: Sequence[ModelMessage]) -> list[dict[str, Any]]:
    """Translate a list of PydanticAI messages into GigaChat ``messages`` array."""
    out: list[dict[str, Any]] = []
    for msg in messages:
        if isinstance(msg, ModelRequest):
            out.extend(_request_to_gigachat(msg))
        elif isinstance(msg, ModelResponse):
            out.append(_response_to_gigachat(msg))
        else:  # pragma: no cover - exhaustive by typing
            raise TypeError(f"Unsupported message type: {type(msg)!r}")
    return out


def _request_to_gigachat(req: ModelRequest) -> Iterable[dict[str, Any]]:
    for part in req.parts:
        if isinstance(part, SystemPromptPart):
            yield {"role": "system", "content": part.content}
        elif isinstance(part, UserPromptPart):
            yield {"role": "user", "content": _user_content_to_text(part.content)}
        elif isinstance(part, ToolReturnPart):
            yield {
                "role": "function",
                "name": part.tool_name,
                "content": _tool_return_to_text(part.content),
            }
        elif isinstance(part, RetryPromptPart):
            # Surface validation feedback as a user turn so the model retries.
            yield {"role": "user", "content": _retry_to_text(part)}
        else:  # pragma: no cover - defensive
            raise TypeError(f"Unsupported request part: {type(part)!r}")


def _response_to_gigachat(resp: ModelResponse) -> dict[str, Any]:
    text_chunks: list[str] = []
    function_call: dict[str, Any] | None = None
    for part in resp.parts:
        if isinstance(part, TextPart):
            text_chunks.append(part.content)
        elif isinstance(part, ToolCallPart) and function_call is None:
            # GigaChat only supports a single function_call per assistant message;
            # PydanticAI agents typically issue one at a time, so take the first.
            function_call = {
                "name": part.tool_name,
                "arguments": _coerce_args_to_obj(part.args),
            }
    msg: dict[str, Any] = {"role": "assistant", "content": "".join(text_chunks)}
    if function_call is not None:
        msg["function_call"] = function_call
    return msg


def _user_content_to_text(content: Any) -> str:
    if isinstance(content, str):
        return content
    parts: list[str] = []
    for item in content:
        if isinstance(item, str):
            parts.append(item)
        else:
            text = getattr(item, "text", None) or getattr(item, "content", None)
            if isinstance(text, str):
                parts.append(text)
    return "\n".join(parts)


def _tool_return_to_text(content: Any) -> str:
    if isinstance(content, str):
        return content
    try:
        return json.dumps(content, ensure_ascii=False, default=str)
    except (TypeError, ValueError):
        return str(content)


def _retry_to_text(part: RetryPromptPart) -> str:
    if isinstance(part.content, str):
        body = part.content
    else:
        body = json.dumps(part.content, ensure_ascii=False, default=str)
    if part.tool_name:
        return f"Tool '{part.tool_name}' call failed validation: {body}\nPlease retry."
    return f"Validation failed: {body}\nPlease retry."


def _coerce_args_to_obj(args: str | dict[str, Any] | None) -> dict[str, Any]:
    if args is None:
        return {}
    if isinstance(args, dict):
        return args
    try:
        parsed = json.loads(args)
    except json.JSONDecodeError:
        return {"_raw": args}
    if isinstance(parsed, dict):
        return parsed
    return {"_value": parsed}


# ---------------------------------------------------------------------------
# Tools (outgoing dicts)
# ---------------------------------------------------------------------------


def tools_to_gigachat(tools: Sequence[ToolDefinition]) -> list[dict[str, Any]]:
    """Translate PydanticAI ``ToolDefinition`` list into GigaChat ``functions``.

    We deliberately omit ``return_parameters`` — GigaChat requires it to be a
    JSON Schema object with a top-level ``properties`` map, but PydanticAI's
    ``return_schema`` is a freeform JSON Schema for whatever Python return type
    the tool declared (often ``{"type": "number"}`` or a dict-shaped schema with
    ``additionalProperties`` and no ``properties``). Sending it through caused
    422 ``Field 'properties' is missing`` errors. The field is purely advisory
    for the model, so dropping it is harmless.
    """
    out: list[dict[str, Any]] = []
    for tool in tools:
        entry: dict[str, Any] = {
            "name": tool.name,
            "parameters": tool.parameters_json_schema or {"type": "object", "properties": {}},
        }
        if tool.description:
            entry["description"] = tool.description
        out.append(entry)
    return out


# ---------------------------------------------------------------------------
# GigaChat -> pydantic_ai (incoming SDK models)
# ---------------------------------------------------------------------------


_FINISH_REASON_MAP: dict[str, FinishReason] = {
    "stop": "stop",
    "length": "length",
    "function_call": "tool_call",
    "blacklist": "content_filter",
    "error": "error",
}


def map_finish_reason(value: str | None) -> FinishReason | None:
    if value is None:
        return None
    return _FINISH_REASON_MAP.get(value, "error")


def parts_from_gigachat_message(message: Messages) -> list[ModelResponsePart]:
    """Build PydanticAI response parts from an SDK ``Messages`` object.

    The SDK pads ``content`` to the empty string when the assistant message is a
    pure ``function_call`` reply (the field is non-Optional). Skip empty text
    so we don't emit a no-op ``TextPart``.
    """
    parts: list[ModelResponsePart] = []
    if message.content:
        parts.append(TextPart(content=message.content))
    fn_call = message.function_call
    if fn_call is not None:
        parts.append(
            ToolCallPart(
                tool_name=fn_call.name,
                args=cast("str | dict[str, Any] | None", fn_call.arguments),
            )
        )
    return parts


def usage_from_gigachat(usage_payload: Usage | None) -> dict[str, int]:
    """Pull token counts from an SDK ``Usage`` model; defaults to zeros.

    Maps GigaChat's ``precached_prompt_tokens`` (its prompt-cache hit count) onto
    PydanticAI's ``cache_read_tokens`` so usage tracking reflects cache savings.
    """
    if usage_payload is None:
        return {"input_tokens": 0, "output_tokens": 0, "cache_read_tokens": 0}
    return {
        "input_tokens": usage_payload.prompt_tokens,
        "output_tokens": usage_payload.completion_tokens,
        "cache_read_tokens": usage_payload.precached_prompt_tokens or 0,
    }


def chunk_finish_reason(chunk: ChatCompletionChunk) -> str | None:
    """Pull the (optional) finish_reason from a streaming chunk's first choice."""
    if not chunk.choices:
        return None
    return chunk.choices[0].finish_reason
